pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        vm.assume(depositAmount > 0);
        vm.assume(extraAmount > 0);
        // Deploy adversarial callee that reverts on receiving ETH
        Reverter reverter = new Reverter();
        // Give the reverter contract ETH to deposit
        vm.deal(address(reverter), depositAmount);
        vm.startPrank(address(reverter));
        c.deposit{value: depositAmount}();
        vm.stopPrank();
        // Also deposit from some other address to increase contract balance, making the invariant non-trivial
        address other = address(0x1234);
        vm.deal(other, extraAmount);
        vm.prank(other);
        c.deposit{value: extraAmount}();
        // Record balance before withdrawal attempt
        uint256 balBefore = address(c).balance;
        // Reverter tries to withdrawAll; it will revert (as designed) when receiving ETH
        bool success;
        vm.startPrank(address(reverter));
        try c.withdrawAll() returns (bool callResult) {
            success = true;
        } catch {
            success = false;
        }
        vm.stopPrank();
        // Assert: In correct contract, if the receiver reverts, the call fails and contract balance remains unchanged.
        // In buggy version, the call succeeds and balance decreases.
        assertTrue(success ? address(c).balance == balBefore : address(c).balance == balBefore);
    }
}

