pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        address reverter = address(new Reverter());
        vm.deal(reverter, 1 ether);
        // Deposit to give reverter credit
        vm.prank(reverter);
        c.deposit{value: amount}();

        // Record state before withdrawAll
        uint256 creditBefore = c.credit(reverter);
        uint256 balanceBefore = address(c).balance;

        // Try withdrawAll as reverter; will fail on ETH transfer
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call, if it did not revert, the caller must have received ETH and credit must be cleared.
        // If the call reverted, credit must remain unchanged.
        uint256 creditAfter = c.credit(reverter);
        if (ok) {
            assertTrue(creditAfter == 0 && address(reverter).balance > 1 ether);
        } else {
            assertTrue(creditAfter == creditBefore);
        }
    }
}

