        uint256 creditBefore = c.credit(attackerAddr);
        uint256 balanceBefore = address(c).balance;
        uint256 attackerCreditBefore = c.credit(attackerAddr);

        // Attacker calls withdrawAll, which triggers reentrant call to withdrawAll again
