pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 attackerGas) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(attackerGas >= 100000 && attackerGas <= 3000000);

        // Deploy reentrant attacker
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), depositAmount);

        // Deposit as attacker
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Attacker withdraws, triggering reentrancy with specified gas
        vm.prank(address(attacker));
        try c.withdrawAll{gas: attackerGas}() { } catch { }

        // After the call (whether successful or not), the attacker's credit in `c` must be zero
        // because `credit[msg.sender] = 0` should have been executed before any reentrancy.
        // The buggy version sets credit to zero after the external call, so a reentrant
        // withdrawAll can execute with non-zero credit, leaving credit possibly non-zero.
        uint256 finalCredit = attacker.creditOf(address(attacker));
        assertTrue(finalCredit == 0);
    }
}

contract Attacker {
    C public target;
    uint256 public reentered;

    constructor(address _target) {
        target = C(_target);
    }

    function creditOf(address a) external view returns (uint256) {
        return target.credit(a);
    }

    receive() external payable {
        if (reentered == 0) {
            reentered = 1;
            target.withdrawAll();
        }
    }
}

