pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Deploy a re-entrant attacker helper
        ReenteringReceiver attacker = new ReenteringReceiver();
        address attackerAddr = address(attacker);

        // Fund the attacker account with ether for deposit
        vm.deal(attackerAddr, amount);

        // Deposit into C as the attacker
        vm.prank(attackerAddr);
        c.deposit{value: amount}();

        // Prepare the attacker to call withdrawAll on its first receive
        attacker.setTarget(address(c));

        // Trigger withdrawal leading to reentrancy
        vm.prank(attackerAddr);
        c.withdrawAll();

        // After the call sequence, verify the invariant:
        // Contract's balance should equal its total deposits minus total outstanding credit
        // 'balance' is a public state variable and thus has an auto-generated getter
        uint256 contractBalance = address(c).balance;
        uint256 totalDeposits = c.balance();
        uint256 remainingCredit = attacker.totalCreditAfter();

        assertTrue(contractBalance == totalDeposits - remainingCredit);
    }
}

contract ReenteringReceiver {
    C target;
    bool entered;
    uint256 public totalCreditAfter;

    function setTarget(address _target) external {
        target = C(_target);
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.withdrawAll();
        }
        totalCreditAfter = target.credit(address(this));
    }
}

