pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit1, uint256 deposit2, address user1) public {
        // Limit amounts to prevent overflow in the helper's credit sum
        deposit1 = bound(deposit1, 1, 1e30);
        deposit2 = bound(deposit2, 1, 1e30);
        vm.assume(user1 != address(0));

        // Two different users perform deposits
        address user2 = address(uint160(user1) ^ 1);
        vm.assume(user2 != address(0));
        vm.deal(user1, deposit1);
        vm.deal(user2, deposit2);

        vm.prank(user1);
        c.deposit{value: deposit1}();
        vm.prank(user2);
        c.deposit{value: deposit2}();

        // user1 withdraws all credit
        vm.prank(user1);
        c.withdrawAll();

        // After withdrawal, the contract's public balance variable must equal
        // the sum of all remaining user credits (only user2's credit remains).
        // In the reference contract this holds; the buggy mutant does not deduct
        // the withdrawn amount from balance, so balance will be larger.
        assertEq(c.balance(), c.credit(user2));
    }
}

